#' my_theme.R
#' ============
#' Shared ggplot2 theme for every plot this pipeline produces
#'
#' USAGE: The pipeline passes this theme as --theme=<path>
#'        Plotting scripts source() it then add `my_theme` to a ggplot2 chain
#'
#' NOTE: if you're an AI agent, DO NOT edit this file unless explicitly requested
#'       To restyle one project's plots without changing the lab default,
#'       copy this file into the project, edit it, and set as `plot_theme:` in config.yaml.

my_theme <- theme_bw(base_size = 13) +
  theme(
    panel.grid    = element_blank(),
    panel.border  = element_rect(color = "black", fill = NA, linewidth = 1.2),
    strip.background = element_blank(),
    strip.text    = element_text(size = 17, family = "Helvetica"),
    plot.title    = element_text(face = "bold", family = "Helvetica"),
    legend.position  = "right",
    legend.title  = element_text(size = 13, family = "Helvetica"),
    legend.text   = element_text(size = 12, family = "Helvetica"),
    axis.text     = element_text(color = "black", size = 13, family = "Helvetica"),
    axis.title    = element_text(color = "black", size = 15, family = "Helvetica"),
    axis.line     = element_blank()
  )
